var DATA = {"mode": "install"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="install"){
  show("Install","pip install pandas");
  show("Since","2008, by Wes McKinney");
  show("Stack","NumPy-based, PyData core");
}else if(m==="df"){
  show("DataFrame",DATA.rows+" rows x "+DATA.cols+" cols");
  show("Think","a spreadsheet with a labeled index");
  show("Columns",DATA.names.join(", "));
}else if(m==="series"){
  show("Series","one labeled column");
  show("Example","df['temp'] -> "+DATA.n+" values");
}else if(m==="read"){
  show("read_csv",DATA.file);
  show("Rows read",DATA.n);
  show("Also","read_excel, read_parquet, read_sql, read_json");
}else if(m==="describe"){
  show("describe()","count, mean, std, min, max per column");
  show("First look","always describe new data");
}else if(m==="loc"){
  show(".loc","label-based indexing");
  show(".iloc","position-based indexing");
  show("Example","df.loc['row_a', 'temp']");
}else if(m==="filter"){
  var rows=DATA.rows.filter(function(r){return r[DATA.col]>DATA.th;});
  show("Boolean mask",DATA.col+" > "+DATA.th);
  show("Rows kept",rows.length+" of "+DATA.rows.length);
}else if(m==="groupby"){
  var g={};
  DATA.rows.forEach(function(r){var k=r[DATA.key];(g[k]=g[k]||[]).push(r[DATA.val]);});
  console.log("df.groupby('"+DATA.key+"')['"+DATA.val+"'].mean():");
  Object.keys(g).forEach(function(k){var a=g[k];console.log("  "+k+": "+(Math.round(a.reduce(function(x,y){return x+y;},0)/a.length*100)/100));});
}else if(m==="merge"){
  show("merge","SQL-style joins: inner, left, right, outer");
  show("On","key columns");
  show("Rows after",DATA.n);
}else if(m==="pivot"){
  show("pivot_table","reshape long data to wide");
  show("Use","summaries by two dimensions");
}else if(m==="apply"){
  var out=DATA.vals.map(function(v){return v*2;});
  show("apply/map","element-wise functions");
  show("Example","["+DATA.vals.join(",")+"] -> ["+out.join(",")+"]");
}else if(m==="missing"){
  show("Missing data","NaN");
  show("dropna()","remove missing rows");
  show("fillna()","fill with a value or method");
}else if(m==="time"){
  show("Time series","DatetimeIndex + resample()");
  show("Example","hourly means from minute data");
}else if(m==="cow"){
  show("Copy-on-write","pandas 2.0+ default");
  show("Means","safer views, often faster");
}else if(m==="io"){
  show("IO","CSV, Excel, Parquet, SQL, JSON, clipboard");
  show("Tip","Parquet for speed, CSV for humans");
}else if(m==="workflow"){
  console.log("Analysis workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
